"""Continue the existing trial without resetting the simulator.

Motion adapters accept Cartesian APIs with named x/y/z (or position) and
yaw arguments. Ambiguous six-dimensional pose conventions are deliberately
not guessed.
"""

import inspect
import math


# Estimate from the 64 existing observations; do not clamp it to the nominal
# placement range or spend another batch of calls estimating the same pose.
HOLE_X = 0.55475
HOLE_Y = 0.03295
HOLE_YAW_DEG = 45.05

INITIAL_TCP = (0.4564, 0.0656, 0.1672)
CLEAR_Z = INITIAL_TCP[2]
STEP_Z = 0.0005
RETRACT = 0.003
FORCE_LIMIT_N = 10.0


def _method(api, names):
    for name in names:
        fn = getattr(api, name, None)
        if callable(fn):
            return fn
    return None


def _xyz(value):
    if isinstance(value, dict):
        if all(k in value for k in ("x", "y", "z")):
            return tuple(float(value[k]) for k in ("x", "y", "z"))
        for key in ("tcp", "position", "translation", "pose"):
            if key in value:
                return _xyz(value[key])
    if isinstance(value, (tuple, list)):
        if len(value) >= 3 and all(
            isinstance(v, (int, float)) for v in value[:3]
        ):
            return tuple(float(v) for v in value[:3])
        if value:
            return _xyz(value[0])
    raise RuntimeError("Unrecognized Cartesian feedback format")


def _force_magnitude(value):
    if isinstance(value, dict):
        if all(k in value for k in ("fx", "fy", "fz")):
            return math.sqrt(sum(float(value[k]) ** 2
                                 for k in ("fx", "fy", "fz")))
        for key in ("force", "forces", "wrench"):
            if key in value:
                return _force_magnitude(value[key])
    if isinstance(value, (int, float)):
        return abs(float(value))
    if isinstance(value, (tuple, list)):
        if len(value) >= 3 and all(
            isinstance(v, (int, float)) for v in value[:3]
        ):
            return math.sqrt(sum(float(v) ** 2 for v in value[:3]))
        if value:
            return _force_magnitude(value[0])
    raise RuntimeError("Unrecognized force feedback format")


class _Controller:
    def __init__(self, api):
        self.api = api
        self.commanded = INITIAL_TCP
        self.read_pose = _method(
            api, ("tcp_pose", "get_tcp_pose", "get_pose", "current_pose")
        )
        self.read_force = _method(
            api, ("get_tcp_force", "get_force", "get_wrench", "wrench", "force")
        )
        self.set_yaw = _method(api, ("set_yaw", "rotate_to_yaw"))
        self.motion = None

        for name in ("move_to", "move_tcp", "move_cartesian", "movel", "move"):
            fn = getattr(api, name, None)
            if not callable(fn):
                continue
            try:
                params = inspect.signature(fn).parameters
            except (TypeError, ValueError):
                continue

            if any(p.kind == inspect.Parameter.POSITIONAL_ONLY
                   for p in params.values()):
                continue

            keys = set(params)
            vector = next(
                (k for k in ("position", "target_position", "xyz")
                 if k in keys), None
            )
            if not {"x", "y", "z"}.issubset(keys) and vector is None:
                continue

            yaw = next(
                (k for k in ("yaw_deg", "yaw_degrees", "yaw_rad", "yaw")
                 if k in keys), None
            )
            if yaw is None and self.set_yaw is None:
                continue

            supplied = {"x", "y", "z"} if vector is None else {vector}
            if yaw:
                supplied.add(yaw)
            supplied.update(("speed", "velocity", "wait", "blocking"))

            unsupported = [
                p.name for p in params.values()
                if p.default is inspect.Parameter.empty
                and p.kind not in (
                    inspect.Parameter.VAR_POSITIONAL,
                    inspect.Parameter.VAR_KEYWORD,
                )
                and p.name not in supplied
            ]
            if unsupported:
                continue

            self.motion = fn
            self.params = params
            self.vector = vector
            self.yaw_parameter = yaw
            break

        if self.motion is None:
            raise RuntimeError(
                "No unambiguous Cartesian motion interface found. "
                "Provide an adapter exposing move_to(x, y, z, yaw_deg, "
                "speed=..., wait=True)."
            )

        if self.read_force is None and self.read_pose is None:
            raise RuntimeError(
                "Contact-safe insertion requires force or actual TCP feedback."
            )

    def position(self):
        if self.read_pose is not None:
            return _xyz(self.read_pose())
        return self.commanded

    def force(self):
        if self.read_force is None:
            return None
        return _force_magnitude(self.read_force())

    def move(self, x, y, z, yaw, speed):
        if self.api.done():
            return

        kwargs = {}
        if self.vector:
            kwargs[self.vector] = [x, y, z]
        else:
            kwargs.update(x=x, y=y, z=z)

        if self.yaw_parameter:
            angle = math.radians(yaw) if self.yaw_parameter == "yaw_rad" else yaw
            kwargs[self.yaw_parameter] = angle

        if "speed" in self.params:
            kwargs["speed"] = speed
        elif "velocity" in self.params:
            kwargs["velocity"] = speed

        if "wait" in self.params:
            kwargs["wait"] = True
        elif "blocking" in self.params:
            kwargs["blocking"] = True

        self.motion(**kwargs)
        self.commanded = (x, y, z)

    def orient_at_clearance(self, yaw):
        if self.yaw_parameter is None:
            # A separate yaw operation is used only with the peg withdrawn.
            self.set_yaw(yaw)


def _offsets():
    """Center-first 0.25-mm lattice, bounded to a 1.5-mm search radius."""
    points = []
    for i in range(-6, 7):
        for j in range(-6, 7):
            if i * i + j * j <= 36:
                points.append((i, j))
    points.sort(key=lambda p: (p[0] ** 2 + p[1] ** 2,
                              math.atan2(p[1], p[0])))
    for i, j in points:
        yield i * 0.00025, j * 0.00025


def run(api):
    if api.done():
        return

    ctl = _Controller(api)
    current = ctl.position()
    yaw = HOLE_YAW_DEG

    # First withdraw vertically; never translate or rotate an engaged peg.
    safe_z = max(CLEAR_Z, current[2])
    ctl.move(current[0], current[1], safe_z, yaw, 0.01)
    ctl.orient_at_clearance(yaw)

    # This height clears the block even if the controlled point is 80 mm
    # above the peg tip. Subsequent descent is feedback-limited rather than
    # assuming that the TCP is the tip.
    approach_z = 0.135
    contact_z = None

    for yaw_offset in (0.0, -1.0, 1.0):
        trial_yaw = yaw + yaw_offset

        for dx, dy in _offsets():
            if api.done():
                return

            current = ctl.position()
            ctl.move(current[0], current[1], safe_z, trial_yaw, 0.01)
            ctl.orient_at_clearance(trial_yaw)

            x, y = HOLE_X + dx, HOLE_Y + dy
            ctl.move(x, y, safe_z, trial_yaw, 0.02)
            ctl.move(x, y, approach_z, trial_yaw, 0.005)

            f = ctl.force()
            if f is not None and f >= FORCE_LIMIT_N:
                ctl.move(x, y, safe_z, trial_yaw, 0.005)
                raise RuntimeError("Unexpected contact above the insertion region")

            if contact_z is not None:
                # Previously measured contact provides a conservative
                # approach height for subsequent probes.
                probe_start = min(approach_z, contact_z + RETRACT)
                ctl.move(x, y, probe_start, trial_yaw, 0.003)

            blocked = False
            while not api.done():
                before = ctl.position()

                # For a tip TCP, z=0.020 is 30 mm insertion. For a TCP above
                # the tip, success should occur earlier; done() is checked
                # after every 0.5-mm step.
                if before[2] <= 0.019:
                    break

                target_z = max(0.019, before[2] - STEP_Z)
                ctl.move(x, y, target_z, trial_yaw, 0.001)

                if api.done():
                    return

                after = ctl.position()
                f = ctl.force()
                stalled = (
                    ctl.read_pose is not None
                    and before[2] - after[2] < 0.0001
                )
                overloaded = f is not None and f >= FORCE_LIMIT_N

                if stalled or overloaded:
                    contact_z = (
                        after[2] if contact_z is None
                        else max(contact_z, after[2])
                    )
                    blocked = True
                    break

            if api.done():
                return

            # Unload vertically before any lateral correction or yaw change.
            current = ctl.position()
            ctl.move(
                current[0], current[1],
                min(safe_z, current[2] + RETRACT),
                trial_yaw, 0.002
            )
            ctl.move(current[0], current[1], safe_z, trial_yaw, 0.005)

            if not blocked:
                raise RuntimeError(
                    "Insertion-depth limit reached without success; "
                    "verify TCP calibration and hole-pose reference frame."
                )

    raise RuntimeError(
        "Bounded insertion search exhausted; peg withdrawn. "
        "Verify the hole-pose calibration: observations are outside the "
        "stated nominal placement range."
    )
