"""Resume the existing trial; never reset the simulator.

Motion adapters below accept explicit Cartesian position/yaw or Cartesian
increment APIs. They deliberately reject unrecognised motion signatures.
Distances are metres and yaw is in degrees.
"""

import inspect
import math


class _Finished(Exception):
    pass


def _check_done(api):
    if api.done():
        raise _Finished


def _decode_pose(value):
    if isinstance(value, dict):
        for key in ("tcp_pose", "tcp", "pose"):
            if key in value:
                return _decode_pose(value[key])
        position = value.get("position", value.get("pos"))
        if position is None and all(k in value for k in ("x", "y", "z")):
            position = [value["x"], value["y"], value["z"]]
        if position is not None:
            return list(map(float, position[:3])), value.get("yaw")
    if isinstance(value, (list, tuple)):
        if len(value) == 2 and isinstance(value[0], (list, tuple)):
            return list(map(float, value[0][:3])), float(value[1])
        if len(value) >= 3 and all(
            isinstance(v, (int, float)) for v in value[:3]
        ):
            return list(map(float, value[:3])), (
                float(value[3]) if len(value) == 4 else None
            )
    return None


def _pose_reader(api):
    for name in ("get_tcp_pose", "tcp_pose", "get_pose", "get_state"):
        fn = getattr(api, name, None)
        if not callable(fn):
            continue
        try:
            inspect.signature(fn).bind()
        except (TypeError, ValueError):
            continue
        initial = _decode_pose(fn())
        if initial is not None:
            return lambda fn=fn: _decode_pose(fn()), initial
    return None, ([0.4564, 0.0656, 0.1672], None)


class _Motion:
    def __init__(self, api):
        self.api = api
        self.read, initial = _pose_reader(api)
        self.position, self.yaw = initial
        self.fn = None

        for name in ("move_tcp", "move_to", "move", "move_cartesian"):
            fn = getattr(api, name, None)
            if not callable(fn):
                continue
            try:
                parameters = inspect.signature(fn).parameters
            except (TypeError, ValueError):
                continue

            names = set(parameters)
            relative = {"dx", "dy", "dz"} <= names
            vector = next(
                (k for k in ("position", "pos", "target_position", "target_pos")
                 if k in names),
                None,
            )
            if relative:
                coordinates = {"dx", "dy", "dz"}
            elif {"x", "y", "z"} <= names:
                coordinates = {"x", "y", "z"}
            elif vector:
                coordinates = {vector}
            else:
                continue

            yaw_key = next(
                (k for k in ("yaw", "yaw_deg", "dyaw", "delta_yaw")
                 if k in names),
                None,
            )
            supported = coordinates | {
                yaw_key, "speed", "velocity", "acceleration", "wait"
            }
            required = {
                k for k, p in parameters.items()
                if p.default is inspect.Parameter.empty
                and p.kind not in (
                    inspect.Parameter.VAR_POSITIONAL,
                    inspect.Parameter.VAR_KEYWORD,
                )
            }
            if not required <= supported:
                continue
            if any(
                p.kind == inspect.Parameter.POSITIONAL_ONLY
                for p in parameters.values()
            ):
                continue
            if relative and self.read is None:
                continue
            if yaw_key in ("dyaw", "delta_yaw") and self.yaw is None:
                continue
            if yaw_key is None and not callable(getattr(api, "set_yaw", None)):
                continue

            self.fn = fn
            self.parameters = parameters
            self.relative = relative
            self.vector = vector
            self.yaw_key = yaw_key
            break

        if self.fn is None:
            raise RuntimeError(
                "No supported Cartesian motion interface. Supply an explicit "
                "position/yaw adapter; do not guess robot command semantics."
            )

    def refresh(self):
        if self.read is not None:
            value = self.read()
            if value is None:
                raise RuntimeError("Lost TCP feedback.")
            self.position, yaw = value
            if yaw is not None:
                self.yaw = yaw

    def go(self, position, yaw, speed):
        _check_done(self.api)
        self.refresh()
        position = list(position)
        kwargs = {}

        if self.relative:
            kwargs.update(zip(
                ("dx", "dy", "dz"),
                (position[i] - self.position[i] for i in range(3)),
            ))
        elif self.vector:
            kwargs[self.vector] = position
        else:
            kwargs.update(zip(("x", "y", "z"), position))

        if self.yaw_key in ("dyaw", "delta_yaw"):
            # A square peg is equivalent under a 90-degree rotation.
            kwargs[self.yaw_key] = (yaw - self.yaw + 45.0) % 90.0 - 45.0
        elif self.yaw_key:
            kwargs[self.yaw_key] = yaw
        elif self.yaw is None or abs(yaw - self.yaw) > 1e-6:
            self.api.set_yaw(yaw)
            self.yaw = yaw
            _check_done(self.api)

        for key, value in (
            ("speed", speed),
            ("velocity", speed),
            ("acceleration", 0.05),
            ("wait", True),
        ):
            if key in self.parameters:
                kwargs[key] = value

        self.fn(**kwargs)
        _check_done(self.api)
        if self.read is None:
            # Only absolute commands are permitted without pose feedback.
            self.position, self.yaw = position, yaw
        else:
            self.refresh()


def _contact_force(api):
    """Return force magnitude if an unambiguous force interface is available."""
    for name in ("get_force", "get_wrench", "read_wrench"):
        fn = getattr(api, name, None)
        if not callable(fn):
            continue
        value = fn()
        if isinstance(value, dict):
            value = value.get("force")
        if isinstance(value, (int, float)):
            return abs(float(value))
        if isinstance(value, (list, tuple)) and len(value) >= 3:
            if all(isinstance(v, (int, float)) for v in value[:3]):
                return math.sqrt(sum(float(v) ** 2 for v in value[:3]))
    return None


def run(api):
    try:
        _check_done(api)
        motion = _Motion(api)

        # The previous 64 observations are tightly clustered outside the
        # nominal placement range. Do not clip them to that range.
        observations = [api.hole_pose() for _ in range(8)]
        xs = sorted(float(p[0][0]) for p in observations)
        ys = sorted(float(p[0][1]) for p in observations)
        measured_x = sum(xs[1:-1]) / 6
        measured_y = sum(ys[1:-1]) / 6

        # Reuse the existing trace rather than restart a long sensing loop.
        x = (64 * 0.5548 + 8 * measured_x) / 72
        y = (64 * 0.03295 + 8 * measured_y) / 72
        c = 64 * math.cos(math.radians(4 * 45.1))
        s = 64 * math.sin(math.radians(4 * 45.1))
        for _, angle in observations:
            c += math.cos(math.radians(4 * float(angle)))
            s += math.sin(math.radians(4 * float(angle)))
        yaw = math.degrees(math.atan2(s, c)) / 4
        yaw += 90 * round((45.1 - yaw) / 90)

        # This policy uses a peg-tip TCP. If the configured TCP is above the
        # tip, expose its known vertical separation as tcp_to_tip_z.
        offset = getattr(api, "tcp_to_tip_z", 0.0)
        offset = float(offset() if callable(offset) else offset)
        if not 0.0 <= offset <= 0.08:
            raise RuntimeError("Invalid TCP-to-tip vertical offset.")

        surface = 0.05 + offset
        hover = surface + 0.004
        target = surface - 0.032  # 32 mm inserted; 18 mm above hole bottom.
        safe = max(motion.position[2], surface + 0.025)

        # Lift before translating or rotating; retain the current orientation
        # during this lift when feedback supplies it.
        lift_yaw = motion.yaw if motion.yaw is not None else yaw
        motion.go(
            [motion.position[0], motion.position[1], safe],
            lift_yaw, 0.015,
        )
        motion.go([x, y, safe], yaw, 0.025)

        # Fine search is in hole coordinates, not world coordinates.
        offsets = [(0, 0)]
        for ring in range(1, 4):
            offsets.extend(
                (i, j)
                for i in range(-ring, ring + 1)
                for j in range(-ring, ring + 1)
                if max(abs(i), abs(j)) == ring
            )

        angle = math.radians(yaw)
        ca, sa = math.cos(angle), math.sin(angle)

        for yaw_adjustment in (0.0, -0.75, 0.75):
            for i, j in offsets:
                _check_done(api)
                u, v = i * 0.0003, j * 0.0003
                px, py = x + ca * u - sa * v, y + sa * u + ca * v

                # Always withdraw before changing lateral position or yaw.
                motion.refresh()
                old_yaw = motion.yaw if motion.yaw is not None else yaw
                motion.go(
                    [motion.position[0], motion.position[1], hover],
                    old_yaw, 0.004,
                )
                trial_yaw = yaw + yaw_adjustment
                motion.go([px, py, hover], trial_yaw, 0.004)

                previous_z = motion.position[2]
                for step in range(1, 73):
                    commanded_z = max(target, hover - step * 0.0005)
                    motion.go(
                        [px, py, commanded_z], trial_yaw, 0.002,
                    )

                    force = _contact_force(api)
                    if force is not None and force > 10.0:
                        break

                    if motion.read is not None:
                        actual_z = motion.position[2]
                        if (
                            commanded_z < surface
                            and actual_z > commanded_z + 0.0003
                            and previous_z - actual_z < 0.0001
                        ):
                            break
                        previous_z = actual_z

                    if commanded_z <= target:
                        break

        # Exhaustion is failure, not success. Leave the peg withdrawn.
        motion.refresh()
        motion.go(
            [motion.position[0], motion.position[1], safe],
            motion.yaw if motion.yaw is not None else yaw,
            0.004,
        )
        raise RuntimeError("Bounded insertion search exhausted; api.done() is false.")

    except _Finished:
        return
